INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Anwendungsentwickler eine App ohne Kenntnisse in Datenbanken programmieren?', 2, '[{"text": "Ja", "correct": true, "because": "Nicht jede App braucht Datenbanken"}, {"text": "Nein", "correct": false, "because": "Datenbanken sind oft optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Versionskontrolle wie Git Pflicht für jeden Anwendungsentwickler?', 2, '[{"text": "Nein", "correct": true, "because": "Solo möglich, aber Teamarbeit braucht es"}, {"text": "Ja", "correct": false, "because": "Nicht absolut vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Anwendungsentwickler nur Frontend machen?', 2, '[{"text": "Ja", "correct": true, "because": "Spezialisierung ist üblich"}, {"text": "Nein", "correct": false, "because": "Fokus kann variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Anwendungsentwickler auch Netzwerke konfigurieren?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerke sind nicht Kernaufgabe"}, {"text": "Ja", "correct": false, "because": "Andere Rollen übernehmen das"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Brauche ich Mathe für Anwendungsentwicklung?', 2, '[{"text": "Ja", "correct": true, "because": "Logik und Algorithmen erfordern es"}, {"text": "Nein", "correct": false, "because": "Grundlagen sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Anwendungsentwickler auch Spiele programmieren?', 2, '[{"text": "Ja", "correct": true, "because": "Mit richtigen Tools wie Unity möglich"}, {"text": "Nein", "correct": false, "because": "Spezialisierung erlaubt es"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Debugging eine Hauptaufgabe für Anwendungsentwickler?', 2, '[{"text": "Ja", "correct": true, "because": "Fehlerbehebung ist zentral"}, {"text": "Nein", "correct": false, "because": "Unvermeidbarer Teil der Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Anwendungsentwickler ohne Englisch auskommen?', 2, '[{"text": "Nein", "correct": true, "because": "Doku und Tools sind oft englisch"}, {"text": "Ja", "correct": false, "because": "Sprache ist essenziell"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutzt ein Anwendungsentwickler typischerweise für Versionskontrolle?', 2, '[{"text": "Git", "correct": true, "because": "Standard in der Branche"}, {"text": "Excel", "correct": false, "because": "Kein Versionskontrolltool"}, {"text": "Notepad", "correct": false, "because": "Nur ein Editor"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter sagte, ich soll eine App schnell fertigstellen. Was ist der erste Schritt?', 3, '[{"text": "Anforderungen klären", "correct": true, "because": "Basis für alles"}, {"text": "Direkt coden", "correct": false, "because": "Planung fehlt"}, {"text": "Design erstellen", "correct": false, "because": "Zu früh"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprache ist für Anwendungsentwickler im Backend oft entscheidend?', 2, '[{"text": "Java", "correct": true, "because": "Robust und weit verbreitet"}, {"text": "HTML", "correct": false, "because": "Nur Frontend"}, {"text": "CSS", "correct": false, "because": "Styling, kein Backend"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin will eine plattformübergreifende App. Was wähle ich?', 3, '[{"text": "Flutter", "correct": true, "because": "Cross-Platform-Framework"}, {"text": "C++", "correct": false, "because": "Zu low-level"}, {"text": "PHP", "correct": false, "because": "Serverseitig"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Fähigkeiten braucht ein Anwendungsentwickler?', 4, '[{"text": "Programmieren", "correct": true, "because": "Kernaufgabe"}, {"text": "Logisches Denken", "correct": true, "because": "Für Problemlösung"}, {"text": "Teamarbeit", "correct": true, "because": "Projekte sind kollaborativ"}, {"text": "Hardware-Reparatur", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Entwicklungsprozess einer Anwendung?', 3, '[{"text": "Planung", "correct": true, "because": "Erster Schritt"}, {"text": "Testen", "correct": true, "because": "Qualitätssicherung"}, {"text": "Deployment", "correct": true, "because": "Veröffentlichung"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Andere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben einen Bug in der App gefunden. Was könnten Anwendungsentwickler tun?', 3, '[{"text": "Code prüfen", "correct": true, "because": "Fehler lokalisieren"}, {"text": "Tests schreiben", "correct": true, "because": "Problem reproduzieren"}, {"text": "Patch deployen", "correct": true, "because": "Lösung ausrollen"}, {"text": "Router neu starten", "correct": false, "because": "Netzwerkproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools sind für Anwendungsentwickler nützlich?', 4, '[{"text": "IDE wie VS Code", "correct": true, "because": "Code schreiben"}, {"text": "Git", "correct": true, "because": "Versionskontrolle"}, {"text": "Jira", "correct": true, "because": "Projektmanagement"}, {"text": "Schraubenzieher", "correct": false, "because": "Hardware"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Anwendungsentwickler nutzen oft Frameworks wie React. b) Sie müssen auch Server warten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Frameworks ja, Server nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Debugging ist Teil der Anwendungsentwicklung. b) Englisch ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Debugging ja, Englisch wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Anwendungsentwickler kann sich auf Mobile Apps spezialisieren. b) Er muss immer in Assembler programmieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezialisierung ja, Assembler nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Anwendungsentwickler arbeitet oft im Team. b) Er braucht keine Tests zu schreiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teamarbeit ja, Tests nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

